(() => {
  const CONTEXT = "jh-ai-edge-submission-context";
  const TRACKED = "jh-ai-edge-submission-tracked";
  const MAX_AGE_MS = 10 * 60 * 1000;

  function read(key) {
    try {
      return JSON.parse(sessionStorage.getItem(key) || "null");
    } catch {
      return null;
    }
  }

  function recent(value, now) {
    return value
      && Number.isFinite(value.timestamp)
      && now - value.timestamp >= 0
      && now - value.timestamp < MAX_AGE_MS;
  }

  function placementFromUrl() {
    const query = new URLSearchParams(location.search);
    return (query.get("source") || query.get("placement") || "newsletter:direct")
      .trim()
      .slice(0, 100);
  }

  function init() {
    if (window.top !== window.self) {
      try {
        window.top.location.replace(window.location.href);
        return;
      } catch {}
    }

    const now = Date.now();
    const context = read(CONTEXT);
    const tracked = read(TRACKED);
    const useContext = recent(context, now);
    const placement = useContext ? context.placement : placementFromUrl();

    if (useContext && tracked?.submission === context.timestamp) return;
    if (!useContext && recent(tracked, now)) return;

    window.JHAnalytics?.track("newsletter_submit", { placement });
    window.JHAnalytics?.track("newsletter_success", { placement });

    try {
      sessionStorage.setItem(
        TRACKED,
        JSON.stringify({
          timestamp: now,
          submission: useContext ? context.timestamp : null,
        }),
      );
      if (useContext) sessionStorage.removeItem(CONTEXT);
    } catch {}
  }

  window.addEventListener("load", init, { once: true });
})();
